{
  "гриб": "Amanita caesarea (Цезарский гриб)",
  "состав": [
    {
      "вещество": "Маннит",
      "содержание": "2–5 % от сухого веса",
      "влияние": "Осмотический агент и источник энергии; в больших количествах может давать лёгкое слабительное действие."
    },
    {
      "вещество": "Трехалоza",
      "содержание": "5–10 % от сухого веса",
      "влияние": "Осмопротектор грибной клетки; для человека нейтральный дисахарид, расщепляется в тонком кишечнике."
    },
    {
      "вещество": "Эритрит",
      "содержание": "1–3 % от сухого веса",
      "влияние": "Полиол, частично ферментируется микрофлорой кишечника, может вызывать лёгкое вздутие при избыточном поступлении."
    },
    {
      "вещество": "Иботеновая кислота",
      "содержание": "< 0,01 % от сухого веса (следовые количества)",
      "влияние": "Агонист ГАМК-рецепторов; в высоких дозах возбуждает нейроны, в следовых количествах A. caesarea клинически не проявляется."
    },
    {
      "вещество": "Мусцимол",
      "содержание": "< 0,005 % от сухого веса (следовые количества)",
      "влияние": "Агонист ГАМК_A-рецепторов, центральный седативный/гипногенный агент; в дозе A. caesarea обычно не вызывает заметного эффекта."
    },
    {
      "вещество": "β-D-Глюканы (полисахариды)",
      "содержание": "5–15 % от сухого веса",
      "влияние": "Иммуномодуляторы: стимулируют фагоциты и NK-клетки; структурный компонент клеточной стенки."
